3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Runs after the owner is built but before it is saved. Sets the owner's {@code namesakeCount} to the
9	 * number of existing owners (those already persisted, so excluding this new one) that share the same
10	 * firstName and lastName, compared case-insensitively. The value is mutated in place via {@code @Val}
11	 * for the save/respond steps to persist and return.
12	 */
13	public class CountNamesakes {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String firstName = owner.getFirstName();
17	        String lastName = owner.getLastName();
18	        long count = ownerRepository.findAll().stream()
19	                .filter(existing -> equalsIgnoreCase(firstName, existing.getFirstName())
20	                        && equalsIgnoreCase(lastName, existing.getLastName()))
21	                .count();
22	        owner.setNamesakeCount((int) count);
23	    }
24	
25	    private static boolean equalsIgnoreCase(String a, String b) {
26	        return a == null ? b == null : a.equalsIgnoreCase(b);
27	    }
28	}
