1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
10	
11	/**
12	 * Runs before {@link BuildOwner}. Rejects the request when any existing owner already has the same
13	 * last name (compared case-insensitively with collapsed whitespace) and the same
14	 * {@link AddressNormalizer normalized} address, by throwing {@link DuplicateHouseholdException}
15	 * (handled as 409). The check is skipped when the request opts in with {@code sharesHousehold: true},
16	 * which permits several owners to share a household.
17	 */
18	public class EnsureUniqueOwnerHousehold {
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws DuplicateHouseholdException {
22	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
23	            return;
24	        }
25	        String lastName = canonical(request.getLastName());
26	        String address = AddressNormalizer.normalize(request.getAddress());
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (lastName.equals(canonical(existing.getLastName()))
29	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
30	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
31	            }
32	        }
33	    }
34	
35	    /** Lower-cased, trimmed, with any run of whitespace collapsed to a single space. */
36	    private static String canonical(String value) {
37	        if (value == null) {
38	            return "";
39	        }
40	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
41	    }
42	}
