1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	
13	/**
14	 * Runs after {@link BuildOwner}. When the request opts in with {@code sharesHousehold: true}, assigns
15	 * the new owner a {@code householdId} shared by every owner with the same last name (compared
16	 * case-insensitively with collapsed whitespace) and the same {@link AddressNormalizer normalized}
17	 * address, and back-fills that same id onto the existing household members, so both sides carry it. The
18	 * id is derived deterministically from the canonical last name and the normalized address, so it is
19	 * stable across requests. Owners that do not opt in keep a null householdId.
20	 */
21	public class AssignOwnerHousehold {
22	
23	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
24	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
25	            return;
26	        }
27	        String lastName = canonical(owner.getLastName());
28	        String address = AddressNormalizer.normalize(owner.getAddress());
29	        String householdId = householdId(lastName, address);
30	        owner.setHouseholdId(householdId);
31	        for (Owner existing : ownerRepository.findAll()) {
32	            if (lastName.equals(canonical(existing.getLastName()))
33	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))
34	                    && !householdId.equals(existing.getHouseholdId())) {
35	                existing.setHouseholdId(householdId);
36	                ownerRepository.save(existing);
37	            }
38	        }
39	    }
40	
41	    /** Stable, shared household id: the first 16 upper-hex chars of SHA-256 over the canonical
42	     *  last name and address, so all members of a household derive the same value. */
43	    private static String householdId(String lastName, String address) {
44	        try {
45	            byte[] hash = MessageDigest.getInstance("SHA-256")
46	                    .digest((lastName + "\n" + address).getBytes(StandardCharsets.UTF_8));
47	            StringBuilder sb = new StringBuilder(16);
48	            for (int i = 0; i < 8; i++) {
49	                sb.append(String.format("%02X", hash[i]));
50	            }
51	            return sb.toString();
52	        }
53	        catch (NoSuchAlgorithmException ex) {
54	            throw new IllegalStateException("SHA-256 not available", ex);
55	        }
56	    }
57	
58	    /** Lower-cased, trimmed, with any run of whitespace collapsed to a single space. */
59	    private static String canonical(String value) {
60	        if (value == null) {
61	            return "";
62	        }
63	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
64	    }
65	}
