5	import net.officefloor.plugin.variable.Out;
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.mapper.OwnerMapper;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.util.BusinessDay;
11	
12	public class BuildOwner {
13	
14	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
15	        Owner owner = ownerMapper.toOwner(request);
16	        LocalDate registrationDate = owner.getRegistrationDate();
17	        if (registrationDate == null) {
18	            registrationDate = LocalDate.now();
19	        }
20	        // The effective registration date must fall on a business day, whether it was supplied or
21	        // defaulted. Everything derived from it (e.g. the membership number's year) reads it back.
22	        owner.setRegistrationDate(BusinessDay.adjust(registrationDate));
23	        built.set(owner);
24	    }
25	}
